//! What a failure trace and a diagnostic name when the code at fault was generated by a macro
//! (RFC-0056, "Blame"): the user's own expression where a generated token can carry its span
//! (a filter, a condition, a `Not[...]`), and otherwise the call the code was generated for,
//! never another call of the module.
const std = @import("std");
const scratch = @import("scratch.zig");
const types = @import("types.zig");
const modules = @import("modules.zig");
const harness = @import("generic_function_tests.zig");

/// The text each recorded failure of `x` is blamed on, in order.
fn expectBlamed(x: anytype, source: []const u8, expected: []const []const u8) !void {
    const failures = x.failures[0..@min(x.failures.len, x.failure_count)];
    if (failures.len != expected.len) {
        for (failures) |failure| std.debug.print("failure at {d}..{d}: {s}\n", .{ failure.span.start, failure.span.end, source[failure.span.start..failure.span.end] });
    }
    try std.testing.expectEqual(expected.len, failures.len);
    for (failures, expected) |failure, text| {
        // A trace never points into a library block.
        try std.testing.expect(failure.span.end <= source.len);
        try std.testing.expectEqualStrings(text, source[failure.span.start..failure.span.end]);
    }
}

fn expectDiagnostic(h: *harness.Harness, source: []const u8, code: types.Diagnostic.Code, text: []const u8) !void {
    const r = h.front.compile(source);
    if (r == .ok) std.debug.print("unexpected admission: {s}\n", .{source});
    try std.testing.expect(r == .failed);
    if (r.failed.code != code) std.debug.print("diagnostic for {s}: {s}\n", .{ source, r.failed.message() });
    try std.testing.expectEqual(code, r.failed.code);
    try std.testing.expect(r.failed.span.end <= source.len);
    const blamed = source[r.failed.span.start..r.failed.span.end];
    if (!std.mem.eql(u8, text, blamed)) std.debug.print("diagnostic at {d}: {s}\n", .{ r.failed.span.start, source });
    try std.testing.expectEqualStrings(text, blamed);
}

const prelude = "Xs:[]i64=array{1,2,3}\nM:map(i64,i64)=map{1=>10,3=>30}\nPlain<public>:[]i64=For(X:Xs,X*2)\n";

test "a failing filter, binding and index of a general For are each traced to themselves" {
    const h = try harness.create();
    defer scratch.release(h);
    // X = 1: the filter fails. X = 2: the binding's lookup fails. X = 3: the body's index fails.
    const source = prelude ++ "A<public>:[]i64=For(X:Xs,Y:=M[X],Y>10,Xs[X]+Y)\n";
    const x = try h.execute(source);
    try std.testing.expectEqual(@as(usize, 0), x.elements(x.get("A").?).?.len);
    // The filter was blamed on `Plain`'s loop, the first macro call of the module.
    try expectBlamed(x, source, &.{ "Y>10", "[", "[" });
    try std.testing.expectEqual(@as(u32, @intCast(std.mem.indexOf(u8, source, "M[X]").? + 1)), x.failures[1].span.start);
    try std.testing.expectEqual(@as(u32, @intCast(std.mem.indexOf(u8, source, "Xs[X]+Y").? + 2)), x.failures[2].span.start);
}

test "filters of a nested, a returning and a carrying For are traced to themselves" {
    const h = try harness.create();
    defer scratch.release(h);
    const nested = prelude ++ "A<public>:[]i64=For(X:Xs,X>2,Y:Xs,Y<2,X*10+Y)\n";
    var x = try h.execute(nested);
    try std.testing.expectEqual(@as(usize, 1), x.elements(x.get("A").?).?.len);
    // Two elements fail the outer filter; for the third, two inner elements fail theirs.
    try expectBlamed(x, nested, &.{ "X>2", "X>2", "Y<2", "Y<2" });
    const leaving = prelude ++ "F()<transacts>:i64=Block{For(X:Xs,X!=1,If(X==3,Return(X),false));0}\nA<public>:i64=F()\n";
    x = try h.execute(leaving);
    try std.testing.expectEqual(@as(i64, 3), x.get("A").?.integer);
    try expectBlamed(x, leaving, &.{"X!=1"});
    const carrying = prelude ++ "F()<transacts>:i64=Block{var T:i64=0;For(X:Xs,X!=2,Block{set T=T+X;T});T}\nA<public>:i64=F()\n";
    x = try h.execute(carrying);
    try std.testing.expectEqual(@as(i64, 4), x.get("A").?.integer);
    try expectBlamed(x, carrying, &.{"X!=2"});
}

test "a failing condition of an If and of a While, and a Not that holds, are traced to themselves" {
    const h = try harness.create();
    defer scratch.release(h);
    const conditions = prelude ++ "A<public>:i64=If(Z:=M[1],Z>10,Z,-1)\nB<public>:i64=If(Xs.Length>5,Xs.Length>0,1,2)\n";
    var x = try h.execute(conditions);
    try std.testing.expectEqual(@as(i64, -1), x.get("A").?.integer);
    try expectBlamed(x, conditions, &.{ "Z>10", "Xs.Length>5" });
    const loop = prelude ++ "F()<transacts>:i64=Block{var I:i64=0;While(N:=Xs[I],N<3,set I=I+1);I}\nA<public>:i64=F()\n";
    x = try h.execute(loop);
    try std.testing.expectEqual(@as(i64, 2), x.get("A").?.integer);
    try expectBlamed(x, loop, &.{"N<3"});
    // `Not[E]` fails when `E` succeeds: the whole form is what failed. (The failure of `E`
    // itself, in the second, is the index's.)
    // RFC-0076 rule 5: a bare comparison as the body of `Not` is a dropped comparison, so the
    // body is a `Require`.
    const negation = prelude ++ "A<public>:i64=Attempt(Block{Not[Require[Xs[0]>0]];1},2)\nB<public>:i64=Attempt(Block{Not[Require[Xs[9]>0]];1},2)\n";
    x = try h.execute(negation);
    try std.testing.expectEqual(@as(i64, 2), x.get("A").?.integer);
    try std.testing.expectEqual(@as(i64, 1), x.get("B").?.integer);
    try expectBlamed(x, negation, &.{ "Not[Require[Xs[0]>0]]", "[" });
}

test "a First that finds nothing in an inner level is traced to its own call" {
    const h = try harness.create();
    defer scratch.release(h);
    // For each X no Y exceeds 5: the inner level is empty and the outer iteration fails, three
    // times; then the call itself fails.
    const source = prelude ++ "A<public>:i64=Attempt(First[X:Xs,Y:Xs,Y>5,X],-1)\n";
    const x = try h.execute(source);
    try std.testing.expectEqual(@as(i64, -1), x.get("A").?.integer);
    const failures = x.failures[0..@min(x.failures.len, x.failure_count)];
    try std.testing.expect(failures.len >= 4);
    for (failures) |failure| {
        const text = source[failure.span.start..failure.span.end];
        // The filter, or the call: never `Plain`'s loop.
        if (!std.mem.eql(u8, text, "Y>5") and !std.mem.eql(u8, text, "First")) {
            std.debug.print("blamed: {s} at {d}\n", .{ text, failure.span.start });
            return error.TestUnexpectedResult;
        }
        try std.testing.expect(failure.span.start > prelude.len);
    }
}

test "a diagnostic about generated code names the call it was generated for" {
    const h = try harness.create();
    defer scratch.release(h);
    // Each program has a correct loop first: the module's first macro call, which every
    // diagnostic about generated code used to name.
    const second = "For";
    // A source that cannot be iterated, in a general and in an established loop.
    try expectDiagnostic(h, prelude ++ "B<public>:[]i64=For(X:5,Y:Xs,X+Y)", .type_mismatch, second);
    // The value of a loop used as another type, at top level and in a function.
    try expectDiagnostic(h, prelude ++ "B<public>:[]string=For(X:Xs,Y:Xs,X+Y)", .type_mismatch, second);
    try expectDiagnostic(h, prelude ++ "F()<computes>:[]string=For(X:Xs,Y:Xs,X+Y)\nB<public>:[]string=F()", .type_mismatch, second);
    // `Not` outside a failure context: the form itself.
    try expectDiagnostic(h, prelude ++ "B<public>:logic=Not[Xs[5]>0]", .failure_context_required, "Not[Xs[5]>0]");
    // A filter that is no `logic` is found where the generated requirement closes: its loop.
    try expectDiagnostic(h, prelude ++ "B<public>:[]i64=For(X:Xs,Y:Xs,X+Y,X)", .type_mismatch, second);
    // A `While` over locals it cannot carry, after the correct `For`.
    try expectDiagnostic(h, prelude ++ "F(N:i64)<transacts>:i64=Block{While(N<3,set N=N+1);N}\nB<public>:i64=F(0)", .not_mutable, "N");
    // The second of two loops in a function, and the inner of two nested ones.
    for ([_][]const u8{
        prelude ++ "F()<computes>:i64=Block{For(X:Xs,X);For(X:7,X).Length}\nB<public>:i64=F()",
        prelude ++ "B<public>:[][]i64=For(X:Xs,For(Y:X,Y))",
    }) |source| {
        const r = h.front.compile(source);
        try std.testing.expect(r == .failed);
        try std.testing.expectEqualStrings(second, source[r.failed.span.start..r.failed.span.end]);
        // The last `For` of the text is the one at fault.
        try std.testing.expectEqual(std.mem.lastIndexOf(u8, source, "For").?, r.failed.span.start);
    }
}

test "in a bundle a diagnostic about generated code stays in its module, at its call" {
    const h = try harness.create();
    defer scratch.release(h);
    const inputs = [_]modules.Input{
        .{ .path = "main.forb", .source = "L:=import{\"lib.forb\"}\nXs:[]i64=array{1}\nA<public>:[]i64=For(X:Xs,X)+L.Twice()" },
        .{ .path = "lib.forb", .source = "Xs:[]i64=array{4,5}\nOk()<computes>:[]i64=For(X:Xs,X)\nTwice<public>()<computes>:[]i64=For(X:Xs,Y:9,X*Y)" },
    };
    const result = h.front.compileBundle(.{ .root = "main.forb", .modules = &inputs });
    try std.testing.expect(result == .failed);
    try std.testing.expectEqualStrings("lib.forb", result.failed.path);
    const source = inputs[1].source;
    try std.testing.expectEqual(std.mem.lastIndexOf(u8, source, "For").?, result.failed.diagnostic.span.start);
}
